@ zx_guest_head.S -- the front of a ThreadX guest's partition window.
@
@ WHAT THIS FILE IS FOR
@
@   Three things live at fixed offsets in a partition window, and all three
@   are here because both sides of the hypervisor boundary have to agree
@   about where they are:
@
@     +0x00   the readback mailbox, two granules, zero-filled
@     +0x80   one branch to the kernel's own reset symbol
@     +0x84   the image header: which window this image was linked for
@
@   Those three ARE the contract, and only those three: they are declared in
@   examples/common/zx_guest_abi.h and asserted by the guest's linker script,
@   so a section that grew past its slot fails the LINK rather than moving an
@   entry point the hypervisor computes as a compile-time constant.
@
@   The guest's own EL1 vector table follows, 32-byte aligned as VBAR
@   requires, and its address is deliberately NOT part of the contract: the
@   guest writes VBAR from the symbol, so the linker may put the table
@   wherever it likes and the hypervisor never needs to know where.
@
@ WHY THE MAILBOX IS ASSEMBLED HERE AND NOT DECLARED IN C
@
@   Because it must be a LOADED section outside .bss, and there is no way to
@   ask a C compiler for that which is clearer than sixteen words of zeros in
@   a named section.  A C object in .bss would be wiped by the kernel's own
@   reset path AFTER the hypervisor had written the handover into it, and a
@   NOLOAD section would be skipped by objcopy and shift the whole blob by a
@   granule.  The reasoning is in zx_guest_abi.h; this is where it lands.
@
@ WHY THE GUEST INSTALLS ITS OWN VECTORS
@
@   The port's entry.S gives EL1 a vector table whose handlers report through
@   semihosting and then HALT.  That is right for a standalone kernel on a
@   bench and wrong for a partition: a stage-1 fault would stop the model with
@   no way for the hypervisor to learn what happened, and a regression could
@   not tell that from a hang.
@
@   So the guest replaces VBAR with the table below, in which a data abort
@   RECORDS ITS SYNDROME IN THE MAILBOX AND HANDS CONTROL BACK.  That is what
@   makes a stage-1 fault a reported event.  It also demonstrates something a
@   later phase needs anyway: VBAR is per-guest state, a guest owns it, and a
@   partition switch has to save and restore it.
@
@   Replacing it is ordinary guest code -- VBAR is writable at EL1 -- and
@   requires no change whatever to ports/cortex_r52.
@
@ WHICH TABLE WINS FOR AN INTERRUPT, AND WHY IT IS NOT THIS ONE
@
@   Once a partition has a timer of its own, one vector in this table stops
@   being a diagnostic and becomes the kernel's scheduling path.  Two tables
@   then have a claim on it: this one, which the guest installed, and the
@   port's, whose IRQ vector is a branch into _tx_thread_context_save and is
@   the only correct way to enter a ThreadX interrupt handler.
@
@   The answer is BOTH, in the only order that works.  VBAR keeps pointing
@   here -- so a fault is still reported rather than halting the model -- and
@   the IRQ slot is a single branch to the port's own el1_irq_entry.  The
@   context save, the handler call and the restore are then the PORT'S code,
@   unmodified and identical to the one a standalone kernel runs.
@
@   Writing an interrupt entry sequence here instead was the alternative, and
@   it would have been a second implementation of the most delicate assembly
@   in the port: _tx_thread_context_save adjusts LR to find the point of
@   interrupt, and the branch to it must be a plain B rather than a BL for
@   exactly that reason.  A guest that gets that subtly wrong does not fail
@   at the vector -- it corrupts one thread's resume address and fails
@   somewhere else entirely.
@
@   el1_irq_entry exists only when the guest is built with the port's
@   TX_R52_USE_THREADX_IRQ, which is also what makes the port call board_init
@   from its low-level initialisation.  The ZoneX guest is always built with
@   it; whether a tick actually arrives is decided per excursion by a word in
@   the mailbox, so the cooperative and preemptive runs are the same bytes.
@
@ WHY A STAGE-1 FAULT AND A STAGE-2 FAULT CANNOT BE CONFUSED
@
@   They arrive in different places.  A stage-2 violation is a fault in the
@   EL2 translation regime and is taken to EL2, where the hypervisor's own
@   report names it.  A stage-1 fault is taken to EL1, HERE, and the
@   hypervisor only ever learns of it because this handler tells it.  The two
@   reports are produced by different code at different privilege levels and
@   say so, which is a stronger guarantee than two branches of one report.

#include "zx_guest_abi.h"

    .syntax unified
    .arm

/**************************************************************************/
/*  The readback mailbox: two granules at the window base.                 */
/*                                                                        */
/*  Thirty-two words of zero, in its own loaded section.  The hypervisor   */
/*  writes the handover fields into it after copying the image and reads    */
/*  the reported ones out afterwards; stage-2 AP cannot deny EL2 access to  */
/*  a partition's memory, which is what makes the mailbox free.            */
/*                                                                        */
/*  The second granule is what a guest with a timer of its own has to say,  */
/*  and it costs nothing at stage 2 -- the partition window is one region   */
/*  covering the whole of it.  It does cost the guest's stage-1 region for  */
/*  the mailbox 64 more bytes, and it moves the entry branch, which is why  */
/*  the offsets in zx_guest_abi.h and the ASSERTs in the guest's linker     */
/*  script both name 0x80 rather than 0x40.                                */
/**************************************************************************/

    .section .zx_guest_mailbox, "aw", %progbits
    .balign 64
    .global zx_guest_mailbox
zx_guest_mailbox:
    .space  ZX_GD_WINDOW_SIZE, 0
    .size   zx_guest_mailbox, . - zx_guest_mailbox

/**************************************************************************/
/*  The entry branch.                                                     */
/*                                                                        */
/*  The hypervisor ERETs to the window base plus a compile-time constant,  */
/*  so something predictable has to be there.  A kernel's reset symbol is   */
/*  wherever its linker put it -- after two vector tables, in this port --  */
/*  so this is one PC-relative branch to it and nothing else.              */
/*                                                                        */
/*  A32, and that is load-bearing rather than incidental: the hypervisor    */
/*  sets SPSR_hyp for the ERET, and if SPSR.T disagreed with the state of   */
/*  the instruction at the entry the guest would die on its first           */
/*  instruction with an undefined-instruction exception that looks exactly  */
/*  like a bad entry address.  The port's own _start is A32 when it is      */
/*  built to boot at EL1, and this matches it.                             */
/**************************************************************************/

    .section .zx_guest_head, "ax", %progbits
    .balign 64
    .global zx_guest_entry
    .type   zx_guest_entry, %function
zx_guest_entry:
    b       _start
    .size   zx_guest_entry, . - zx_guest_entry

/**************************************************************************/
/*  The image header, immediately after the branch.                       */
/*                                                                        */
/*  WHAT PROBLEM THIS SOLVES.  A guest is LINKED for one partition's       */
/*  window: every absolute address in it -- every literal pool entry, its  */
/*  VBAR, its own MPU bases -- is baked in.  The hypervisor, holding a raw */
/*  blob, has no symbol table and no way to know which window that was.    */
/*                                                                        */
/*  And the failure is a slow one.  The entry branch is PC-relative, so a  */
/*  guest copied into the wrong window STARTS: it runs until its first     */
/*  literal pool load, then reads or writes an address in somebody else's  */
/*  partition -- or in nobody's -- and takes a stage-2 fault whose report  */
/*  points at a guest PC that looks perfectly reasonable.  Nothing in that */
/*  chain says "this image was built for a different address".            */
/*                                                                        */
/*  So the guest declares it.  Three words the loader can check before it  */
/*  ERETs anywhere:                                                       */
/*                                                                        */
/*    +0x44  the window base this image was linked for                    */
/*    +0x48  the window size it was linked to fit                         */
/*    +0x4C  a magic number saying it is a ZoneX guest at all             */
/*                                                                        */
/*  The magic earns its four bytes twice over: a window that was never     */
/*  written reads as zero, and an .incbin whose input pattern matched      */
/*  nothing produces an empty section rather than an error, so "the first  */
/*  word of the image is not the magic" catches both.                     */
/**************************************************************************/

    .global zx_guest_image_header
zx_guest_image_header:
    .word   __zx_guest_window_base
    .word   __zx_guest_window_size
    .word   ZX_GUEST_IMAGE_MAGIC
    .size   zx_guest_image_header, . - zx_guest_image_header

/**************************************************************************/
/*  The guest's own EL1 vector table.                                     */
/*                                                                        */
/*  32-byte aligned, as VBAR requires.  Every entry that is not the data   */
/*  abort reports itself through the same handler with a different code,   */
/*  because a vector that fell through is how a fault becomes a hang.      */
/**************************************************************************/

    .section .zx_guest_vectors, "ax", %progbits
    .balign 32
    .global zx_guest_vectors
zx_guest_vectors:
    b       zx_guest_trap_reset             @ 0x00  reset
    b       zx_guest_trap_undef             @ 0x04  undefined instruction
    b       zx_guest_trap_svc               @ 0x08  supervisor call
    b       zx_guest_trap_pabt              @ 0x0C  prefetch abort
    b       zx_guest_trap_dabt              @ 0x10  data abort
    b       zx_guest_trap_reserved          @ 0x14  reserved
    b       zx_guest_trap_irq               @ 0x18  IRQ
    b       zx_guest_trap_fiq               @ 0x1C  FIQ

    .text
    .balign 4

/**************************************************************************/
/*  zx_guest_trap_dabt -- a stage-1 data abort, reported rather than fatal. */
/*                                                                        */
/*  DFSR and DFAR are read FIRST, before anything else can disturb them,   */
/*  and written into the mailbox with the progress bit that says a stage-1  */
/*  fault happened.  Then HVC #1 hands the machine back to the hypervisor,  */
/*  which reads the mailbox and reports.                                   */
/*                                                                        */
/*  THE MAILBOX ADDRESS IS REACHED THROUGH A LITERAL, WHICH IS SAFE HERE    */
/*  AND WOULD NOT BE IN THE RELOCATABLE PROBE BLOB.  This image is LINKED    */
/*  for its window: every absolute address in it is already correct, and     */
/*  the loader copies it to the address it was linked for.  The blob in      */
/*  examples/common/zx_payload.S is the opposite case -- one program copied   */
/*  into two different windows -- and that is why it takes a base pointer    */
/*  in r0 instead.  Two guests, two disciplines, and mixing them up          */
/*  produces a guest that works in one partition and not the other.         */
/*                                                                        */
/*  No stack is used.  SP_abt exists -- the port's el1_entry gave every mode */
/*  a stack -- but a handler that pushes nothing cannot be the thing that    */
/*  overflows while reporting why something else went wrong.                */
/**************************************************************************/

    .macro  ZX_GUEST_REPORT_AND_YIELD code
    mrc     p15, 0, r0, c5, c0, 0           @ DFSR
    mrc     p15, 0, r1, c6, c0, 0           @ DFAR
    ldr     r2, =zx_guest_mailbox
    str     r0, [r2, #ZX_GD_FAULT_STATUS]
    str     r1, [r2, #ZX_GD_FAULT_ADDRESS]
    ldr     r0, [r2, #ZX_GD_STAGE1]
    orr     r0, r0, #\code
    str     r0, [r2, #ZX_GD_STAGE1]
    dsb
    hvc     #ZX_HVC_GUEST_YIELD
    .endm

    .global zx_guest_trap_dabt
    .type   zx_guest_trap_dabt, %function
zx_guest_trap_dabt:
    ZX_GUEST_REPORT_AND_YIELD ZX_GS_DABT
zx_guest_trap_dabt_hang:
    b       zx_guest_trap_dabt_hang
    .size   zx_guest_trap_dabt, . - zx_guest_trap_dabt

/**************************************************************************/
/*  The other seven vectors.                                              */
/*                                                                        */
/*  A prefetch abort reads IFSR and IFAR rather than DFSR and DFAR, and     */
/*  the rest have no fault registers at all -- so they share the same       */
/*  reporting shape with whatever the syndrome registers happen to hold.    */
/*  What matters is that each one is DISTINGUISHABLE: a run that reported    */
/*  "the guest stopped" without saying which vector took it would send the   */
/*  reader to the wrong half of the kernel.                                 */
/**************************************************************************/

    .type   zx_guest_trap_pabt, %function
zx_guest_trap_pabt:
    mrc     p15, 0, r0, c5, c0, 1           @ IFSR
    mrc     p15, 0, r1, c6, c0, 2           @ IFAR
    ldr     r2, =zx_guest_mailbox
    str     r0, [r2, #ZX_GD_FAULT_STATUS]
    str     r1, [r2, #ZX_GD_FAULT_ADDRESS]
    ldr     r0, [r2, #ZX_GD_STAGE1]
    orr     r0, r0, #ZX_GS_PABT
    str     r0, [r2, #ZX_GD_STAGE1]
    dsb
    hvc     #ZX_HVC_GUEST_YIELD
zx_guest_trap_pabt_hang:
    b       zx_guest_trap_pabt_hang
    .size   zx_guest_trap_pabt, . - zx_guest_trap_pabt

    .macro  ZX_GUEST_TRAP_OTHER name, code
    .type   \name, %function
\name:
    ldr     r2, =zx_guest_mailbox
    ldr     r0, [r2, #ZX_GD_STAGE1]
    orr     r0, r0, #\code
    str     r0, [r2, #ZX_GD_STAGE1]
    mov     r0, #0
    str     r0, [r2, #ZX_GD_FAULT_STATUS]
    str     r0, [r2, #ZX_GD_FAULT_ADDRESS]
    dsb
    hvc     #ZX_HVC_GUEST_YIELD
1:
    b       1b
    .size   \name, . - \name
    .endm

    ZX_GUEST_TRAP_OTHER zx_guest_trap_reset,    ZX_GS_OTHER
    ZX_GUEST_TRAP_OTHER zx_guest_trap_undef,    ZX_GS_UNDEF
    ZX_GUEST_TRAP_OTHER zx_guest_trap_svc,      ZX_GS_OTHER
    ZX_GUEST_TRAP_OTHER zx_guest_trap_reserved, ZX_GS_OTHER
    ZX_GUEST_TRAP_OTHER zx_guest_trap_fiq,      ZX_GS_OTHER

/**************************************************************************/
/*  zx_guest_trap_irq -- one branch, into the port's own IRQ vector body.  */
/*                                                                        */
/*  A PLAIN B AND NOT A BL, and the difference is not stylistic.  The      */
/*  first thing el1_irq_entry does is branch to _tx_thread_context_save,   */
/*  which adjusts LR to recover the point of interrupt.  Arriving there    */
/*  with LR pointing back into this file would save a resume address       */
/*  inside a trampoline, and the thread would return to the wrong place    */
/*  the next time it was scheduled -- a corruption that shows up nowhere   */
/*  near the vector that caused it.                                        */
/*                                                                        */
/*  Nothing else happens here.  Recording the interrupt in the mailbox     */
/*  would mean touching a register before the port's context save had run, */
/*  which is the one thing that path requires nobody does.  The counting   */
/*  is done in board_irq_handler, which the port calls once the context is */
/*  safe.                                                                  */
/*                                                                        */
/*  WHEN NO TICK WAS GRANTED this vector is installed and never taken: the */
/*  guest's CPU interface is left disabled, so the GIC has nowhere to      */
/*  deliver to.  An interrupt arriving anyway would land in the kernel's   */
/*  own handler and be counted as an unexpected INTID, which is a better   */
/*  outcome than the previous behaviour -- reporting and yielding -- that  */
/*  it replaces, because it says WHICH interrupt arrived.                  */
/**************************************************************************/

    .global zx_guest_trap_irq
    .type   zx_guest_trap_irq, %function
zx_guest_trap_irq:
    b       el1_irq_entry
    .size   zx_guest_trap_irq, . - zx_guest_trap_irq
